# Build acceptance c2 from the failed c1 run.
# c1 stopped at baseline: after the focus writer the shooting screen has no menu
# title, so the copied literal "Y/M/D" is the wrong screen. The recorded title is null.
# c1's files stay. Do not edit this file after it has run.
from pathlib import Path

root = Path('work/scripts')
table = Path('work/scripts/accept_table_c1.json').read_text(encoding='utf-8')
import json
steps = json.loads(table)
changed = 0
for step in steps:
    expect = step.get('expect') or {}
    if expect.get('title') == 'Y/M/D':
        expect['title'] = None
        changed += 1
Path('work/scripts/accept_table_c2.json').write_text(json.dumps(steps, indent=2) + '\n', encoding='utf-8')

runner = Path('work/scripts/accept_runner_c1.mjs').read_text(encoding='utf-8')
repls = [
    ('accept_runner_c1.mjs', 'accept_runner_c2.mjs'),
    ('accept_table_c1.json', 'accept_table_c2.json'),
    ('accept-c1.jsonl', 'accept-c2.jsonl'),
    ('session-accept-c1-', 'session-accept-c2-'),
    ("tag: 'accept-c1-", "tag: 'accept-c2-"),
    ('import-inventory-c1.json', 'import-inventory-c2.json'),
    ('nvram-accept-c1-', 'nvram-accept-c2-'),
    ('highlight: got.highlight,', 'highlight: got.highlight,\n      texts: got.texts,'),
]
for old, new in repls:
    count = runner.count(old)
    if count < 1:
        raise SystemExit('missing ' + old)
    runner = runner.replace(old, new)
note = '// c2: shooting title is null. c1 recorded that after the focus writer. c1 is kept.\n'
if not runner.startswith(note):
    runner = note + runner
Path('work/scripts/accept_runner_c2.mjs').write_text(runner, encoding='utf-8')
print('titles', changed, 'runner', len(runner))
